
import { request } from './request';

export default {
    getYouDataReport(config) {
        const { url, params, ...rest } = config;
        const result = request({
            url,
            method: 'GET',
            headers: { 'Content-Type': 'application/json' },
            params: { ...params },
            ...rest,
        });
        return result;
    },
    getTokenKey () {
        const result = request({
            url: '/api/v1/youdata/getTokenKey',
            method: 'GET',
            headers: { 'Content-Type': 'application/json' },
        });
    return result;
    },
    refreshReportData (config) {
        const { params, ...rest } = config;
        const result = request({
            url: '/api/dash/report/flushReport',
            method: 'GET',
            params: { ...params },
            headers: { 'Content-Type': 'application/json' },
            ...rest,
        });
    return result;
    }
};
