<template>
    <div :class="$style.root">
        <iframe
            ref="iframe"
            v-if="!showDefault"
            v-bind="$attrs"
            :src="url"
            frameborder="0"
            @load="onLoad"
        >
        </iframe>
        <img
            v-else
            :src="require('./assets/default.png')"
            :class="h5Mode() ? $style.emptyImageH5 : $style.emptyImage"
        />
    </div>
</template>

<script>
import queryString from "query-string"
import service from "./services"

export default {
    name: "lcap-report",
    props: {
        mode: { type: String },
        showTitle: { type: Boolean, default: true },
        showScaleBar: { type: Boolean, default: true },
        showPageBar: { type: Boolean, default: true },
        showProgressBar: { type: Boolean, default: true },
        scale: { type: String },
        bottomBarPosTop: { type: String },
        toolbar: {
            type: String,
            default: "print refresh bookmark export doctor",
        },
        reportId: { type: Object, default: () => ({}) },
        selectIdGroup: { type: Array, default: () => [] },
        selectParamGroup: { type: Array, default: () => [] },
        host: { type: String, default: "lcap.bi.test.com" },
    },
    data() {
        return {
            url: "",
            showDefault: false,
            token: "",
        }
    },
    mounted() {
        // IDE开发环境无法获取Token，遂iframe无法展示报表，url无需生成
        this.showDefault = this.$env.VUE_APP_DESIGNER
        if (!this.showDefault) {
            this.getFullUrl()
        }
    },
    methods: {
        async getFullUrl() {
            try {
                //  筛选器参数
                const componentIds = []
                this.selectIdGroup.forEach((item) => {
                    item.selectName !== "" && componentIds.push(item.selectName)
                })
                this.selectParamGroup.forEach((item) => {
                    item.paramName !== "" && componentIds.push(item.paramName)
                })

                // 获取报告的实际id
                const { data = {} } = await service.getYouDataReport({
                    url: "/api/report/getCustomConfig",
                    params: {
                        reportIdList: this.reportId.id,
                        componentIdList: componentIds.join(","),
                    },
                })
                this.token = data.token;
                // 切换为环境中映射的 id
                const selectorMap = this.mappingSelector(data.componentIdMap)
                this.setUrl(
                    {
                        token: data.token,
                        rid: data.reportIdMap[this.reportId.id],
                        defaults: JSON.stringify(selectorMap),
                    },
                    data.projectId
                )
                // 手动更新数据缓存, 目前无法获取httpOnly保护的cookie，暂时注释掉
                // await service.refreshReportData({
                //     params: {
                //         reportId: this.reportId.id,
                //         trigger: "Integrate",
                //         token: this.token,
                //     },
                // })
            } catch (err) {
                console.info(err)
            }
        },
        // 切换为环境中映射的 id
        mappingSelector(idMap = {}) {
            const selectorMap = {}
            this.selectIdGroup.forEach((item) => {
                if (idMap[item.selectName]) {
                    selectorMap[idMap[item.selectName]] = item.selectValue
                }
            })
            this.selectParamGroup.forEach((item) => {
                if (idMap[item.paramName]) {
                    selectorMap[idMap[item.paramName]] = item.paramValue
                }
            })
            return selectorMap
        },
        setUrl(data, projectId) {
            const params = {
                ...data,
                mode: this.mode,
                hideTitle: !this.showTitle,
                hideScaleBar: !this.showScaleBar,
                hidePageBar: !this.showPageBar,
                hideProgressBar: !this.showProgressBar,
                toolbar: JSON.stringify(this.toolbar.split(" ")),
                scale: this.scale,
            }

            if (this.bottomBarPosTop) {
                params.bottomBarPos = "top"
            }
            // 和后端协商，iframe地址中把bi字段插到了低代码域名的第一位之后
            const tenant = window.appInfo.tenant
            const lcDomain =
                window.appInfo.lowcodeDomain ||
                (window.appInfo.envConfig &&
                    window.appInfo.envConfig.lowcodeDomain)
            const leftHost = lcDomain.split(".")[0]
            const rightHost = lcDomain.split(".").slice(1).join(".")
            this.url = `//${tenant}.${leftHost}.bi.${rightHost}/dash/integration/${projectId}/?${queryString.stringify(
                params
            )}`
        },
        onLoad(event) {
            this.$emit("load", event)
        },
        reload() {
            const prevUrl = this.url
            this.url = ""
            this.$nextTick(() => {
                this.url = prevUrl
            })
        },
        h5Mode() {
            console.log("h5", /h5=1/.test(location.href))
            return /h5=1/.test(location.href)
        },
    },
}
</script>

<style module>
