    position: relative;
    display: flex;
    justify-content: center;
    align-items: center;
    height: 800px;
    background: #f7f8fa;
}

.root iframe {
    position: absolute;
    top: 0;
    left: 0;
    bottom: 0;
    right: 0;
    width: 100%;
    height: 100%;
}

.emptyImage {
    height: 40%;
}

.emptyImageH5 {
    width: 80%;
    height: 20%;
}
</style>
